function toggleCollapse(e){let t=document.getElementById(e),l="true"===t.getAttribute("aria-expanded"),n=document.querySelector(".collapseall"),o=document.querySelector(".expandall"),s=document.querySelector(".content.course-content-item-content.collapse");l=!l,t.setAttribute("aria-expanded",l),l?(n.style.display="inline",o.style.display="none",s.classList.add("show")):(n.style.display="none",o.style.display="inline",s.classList.remove("show"))}